<?php $esc=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$asset=function($f){return $f?base_url().'upload/qms_report_assets/'.rawurlencode(basename($f)):'';};$prepared=$settings&&isset($settings->risk_prepared_by)?$settings->risk_prepared_by:'';$approved=$settings&&isset($settings->risk_approved_by)?$settings->risk_approved_by:'';?><!doctype html><html><head><meta charset="utf-8"><title>Opportunity Registry</title><style>@page{size:landscape;margin:12mm}body{font-family:Arial;font-size:11px}.toolbar{margin-bottom:10px}.head{width:100%;max-height:100px;object-fit:contain}.title{text-align:center;font-size:22px;font-weight:bold;margin:10px}.office{font-size:14px;font-weight:bold;margin:10px 0 35px}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #111;padding:7px;vertical-align:top;word-wrap:break-word}th{background:#8eafd5;text-align:center;font-size:13px}.center{text-align:center}.sign{display:flex;justify-content:space-around;margin:40px 8% 0;font-size:13px}.sig{width:35%}.line{border-top:1px solid;margin-top:44px;padding-top:3px;text-align:center;font-weight:bold}.foot{width:100%;max-height:65px;object-fit:contain;margin-top:14px}@media print{.toolbar{display:none}}</style></head><body><div class="toolbar"><button onclick="window.print()">Print / Save PDF</button></div><?php if($settings&&$settings->letterhead_file):?><img class="head" src="<?=$esc($asset($settings->letterhead_file))?>"><?php endif;?><div class="title">OPPORTUNITY REGISTRY</div><div class="office">A. Name of Bureau/Service/Functional Division/School: <?=$esc($sectionName)?></div><h3>B. Opportunity Registry</h3><table><colgroup><col style="width:3%"><col style="width:28%"><col style="width:9%"><col style="width:7%"><col style="width:12%"><col style="width:22%"><col style="width:11%"><col style="width:8%"></colgroup><tr><th>No</th><th>DECLARED PROCESS &amp; OPPORTUNITY STATEMENT</th><th>LIKELIHOOD</th><th>IMPACT</th><th>OPPORTUNITY RATING</th><th>OPPORTUNITY PURSUIT ACTION PLAN</th><th>PERSON/OFFICE RESPONSIBLE</th><th>TARGET DATE</th></tr><?php foreach($entries as $i=>$x):?><tr><td><?=$i+1?></td><td><?=$esc($x->declared_process_opportunity)?></td><td><?=$x->likelihood?></td><td><?=$x->impact?></td><td><?=$x->opportunity_rating?></td><td><?=$esc($x->pursuit_action_plan)?></td><td><?=$esc($x->person_responsible)?></td><td><?=$esc($x->target_date)?></td></tr><?php endforeach;?></table><div class="sign"><div class="sig">Prepared by:<div class="line"><?=$esc($prepared)?></div>Process Holder</div><div class="sig">Approved by:<div class="line"><?=$esc($approved)?></div>Division Chief / Authorized Approver</div></div><?php if($settings&&$settings->footer_file):?><img class="foot" src="<?=$esc($asset($settings->footer_file))?>"><?php endif;?></body></html>
